class DungeonGame:
    def __init__(self):
        self.rooms = {
            "start": {
                "description": "You are in a dark room",
                "exits": {"north": "hall"},
                "items": [],
                "trap": False
            },
            "hall": {
                "description": "You are in a long hall",
                "exits": {"south": "start", "east": "treasure"},
                "items": ["key"],
                "trap": False
            },
            "treasure": {
                "description": "You are in a treasure room",
                "exits": {"west": "hall"},
                "items": ["gold"],
                "trap": True  # Let's assume there's a trap in the treasure room
            }
        }
        self.current_room = "start"
        self.inventory = []
        self.game_is_over = False

    def move(self, direction):
        if self.game_is_over:
            return
        if direction in self.rooms[self.current_room]["exits"]:
            new_room = self.rooms[self.current_room]["exits"][direction]
            if self.rooms[new_room]["trap"]:
                self.trigger_trap()
            else:
                self.current_room = new_room
                print(self.rooms[self.current_room]["description"])
        else:
            print("You can't go that way.")

    def collect_item(self, item_name):
        if self.game_is_over:
            return
        if item_name in self.rooms[self.current_room]["items"]:
            self.inventory.append(item_name)
            self.rooms[self.current_room]["items"].remove(item_name)
            print(f"You picked up {item_name}.")
        else:
            print("That item is not in this room.")

    def trigger_trap(self):
        if self.game_is_over:
            return
        print("You triggered a trap!")
        self.game_over()

    def game_over(self):
        print("Game Over!")
        self.game_is_over = True
```

